function lengthOfLIS(nums) {
  const tails = [];                              // tails[k]: smallest end of an increasing run of length k + 1
  for (const x of nums) {
    let lo = 0, hi = tails.length;               // find the first tail >= x
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (tails[mid] < x) lo = mid + 1;
      else hi = mid;
    }
    tails[lo] = x;                               // append (lo === tails.length) or lower a tail
  }
  return tails.length;
}

from bisect import bisect_left

def length_of_lis(nums):
    tails = []                            # tails[k]: smallest end of an increasing run of length k + 1
    for x in nums:
        k = bisect_left(tails, x)         # the first tail >= x
        if k == len(tails):
            tails.append(x)               # x extends the longest run
        else:
            tails[k] = x                  # x is a smaller end for length k + 1
    return len(tails)

int lengthOfLIS(int[] nums) {
    int[] tails = new int[nums.length];          // tails[k]: smallest end of an increasing run of length k + 1
    int size = 0;
    for (int x : nums) {
        int lo = 0, hi = size;                   // find the first tail >= x
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (tails[mid] < x) lo = mid + 1;
            else hi = mid;
        }
        tails[lo] = x;                           // append (lo == size) or lower a tail
        if (lo == size) size++;
    }
    return size;
}

int lengthOfLIS(vector<int>& nums) {
    vector<int> tails;                           // tails[k]: smallest end of an increasing run of length k + 1
    for (int x : nums) {
        auto it = lower_bound(tails.begin(), tails.end(), x);   // the first tail >= x
        if (it == tails.end()) tails.push_back(x);   // x extends the longest run
        else *it = x;                                // x is a smaller end for that length
    }
    return tails.size();
